const messageText = $json.message?.text || '';
const chatId = $json.message?.chat?.id;

// Catálogo estructurado de comandos para el bot
const COMMAND_REGISTRY = [
  {
    category: "📢 <b>Situaciones Temporales de Agentes IA:</b>",
    commands: [
      {
        name: "/update",
        syntax: "/update <usa|lat|all> <situación>",
        aliases: ["/situacion", "/situaciones"],
        description: "Establece una directiva/situación temporal con vigencia (ej. 'por 24 horas', 'por 3 días', 'hasta nuevo aviso') para orientar a los agentes IA ante contingencias.",
        example: "/update usa El webplayer web.ip365.cx está en mantenimiento por 24 horas. Indicar a los clientes que usen la app."
      },
      {
        name: "/update status",
        syntax: "/update status",
        aliases: ["/situaciones"],
        description: "Muestra el estado de todas las directivas activas y sus respectivos [ID] asignados.",
        example: "/update status"
      },
      {
        name: "/update clear",
        syntax: "/update clear <ID> | /update <usa|lat|all> clear",
        aliases: ["/update del", "/update borrar"],
        description: "Desactiva una directiva específica mediante su ID (ej. /update clear 2) o todas las directivas de un agente.",
        example: "/update clear 2"
      }
    ]
  },
  {
    category: "💳 <b>Generación de Enlaces de Pago:</b>",
    commands: [
      {
        name: "/card2crypto",
        syntax: "/card2crypto monto porcentaje [orden]",
        aliases: ["/c2c"],
        description: "Genera link de pago con tarjeta a cripto (Card2Crypto).",
        example: "/card2crypto 30 10 ttv0810a"
      },
      {
        name: "/nowpayments",
        syntax: "/nowpayments monto porcentaje [orden]",
        aliases: [],
        description: "Genera invoice de pago multimoneda en NOWPayments.",
        example: "/nowpayments 50 0 miorden"
      },
      {
        name: "/pdcash",
        syntax: "/pdcash monto porcentaje [orden]",
        aliases: [],
        description: "Genera enlace de pago en pd.cash.",
        example: "/pdcash 20 5 pedido12"
      },
      {
        name: "/blink",
        syntax: "/blink monto porcentaje [orden]",
        aliases: [],
        description: "Genera factura Lightning USD / Bitcoin en Blink.",
        example: "/blink 24 10 Alvez"
      }
    ]
  },
  {
    category: "🔍 <b>Tracking de Pago Card2Crypto:</b>",
    commands: [
      {
        name: "/card2track",
        syntax: "/card2track <tracking_address>",
        aliases: ["/c2track"],
        description: "Consulta el estado en tiempo real de una transacción en Card2Crypto.",
        example: "/card2track oxVo4FQwRDd..."
      }
    ]
  },
  {
    category: "🤖 <b>Instruir Agente IA de Chatwoot:</b>",
    commands: [
      {
        name: "/agent",
        syntax: "/agent <id_conversacion> <instruccion>",
        aliases: ["/agente"],
        description: "Envía una orden al Agente IA para responder al cliente en Chatwoot respetando nombre e idioma.",
        example: "/agent 1323 envia instrucciones para instalar en iphone"
      }
    ]
  },
  {
    category: "ℹ️ <b>Ayuda y Comandos:</b>",
    commands: [
      {
        name: "/help",
        syntax: "/help",
        aliases: ["/?"],
        description: "Muestra la lista de todos los comandos disponibles y su sintaxis.",
        example: "/help"
      }
    ]
  }
];

function escapeHtml(str) {
  if (!str) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

// Función para generar dinámicamente el mensaje de ayuda en HTML
function generateHelpText() {
  let output = "🤖 <b>Comandos disponibles en @AlvezN8Nbot:</b>\n\n";
  for (const cat of COMMAND_REGISTRY) {
    output += `${cat.category}\n`;
    for (const cmd of cat.commands) {
      output += `• <code>${escapeHtml(cmd.syntax)}</code>\n`;
      if (cmd.aliases && cmd.aliases.length > 0) {
        output += `  <i>(Alias: ${cmd.aliases.map(a => `<code>${escapeHtml(a)}</code>`).join(', ')})</i>\n`;
      }
      if (cmd.description) {
        output += `  ${escapeHtml(cmd.description)}\n`;
      }
      if (cmd.example) {
        output += `  <b>Ejemplo:</b> <code>${escapeHtml(cmd.example)}</code>\n`;
      }
      output += `\n`;
    }
  }
  return output.trim();
}

const helpText = generateHelpText();

// Separar por espacios en blanco y limpiar el comando si incluye @bot
const parts = messageText.trim().split(/\s+/);
let rawCommand = parts[0] ? parts[0].toLowerCase() : '';
const command = rawCommand.split('@')[0]; // Elimina el username del bot si viniera (/help@MiBot -> /help)

let isCard2Crypto = false;
let isNowPayments = false;
let isPdCash = false;
let isBlink = false;
let isAgent = false;
let isCard2Track = false;
let isUpdate = false;
let isHelp = false;

let baseAmount = null;
let percentage = 0;
let finalAmount = null;
let orderid = '';
let conversationId = null;
let instruction = '';
let trackingAddress = '';
let errorMessage = '';

let updateAction = '';
let updateAgent = '';
let updateSituation = '';
let updateDurationText = '';
let updateCreatedAt = '';
let updateExpiresAt = '';
let updateTargetId = null;

if (command === '/help' || command === '/?' || command === '/start' || command === 'help' || command === 'ayuda') {
  isHelp = true;
} else if (command === '/update' || command === '/situacion' || command === '/situaciones') {
  isUpdate = true;
  if (parts.length === 1 || (parts.length > 1 && ['status', 'list', 'ver', 'info', 'listar', 'estado'].includes(parts[1].toLowerCase()))) {
    updateAction = 'status';
  } else {
    const p1 = parts[1].toLowerCase();

    // Case: /update clear [id|agent] OR /update del [id] OR /update borrar [id]
    if (['clear', 'off', 'del', 'delete', 'borrar', 'eliminar', 'desactivar', 'clean'].includes(p1)) {
      if (parts.length >= 3) {
        const p2 = parts[2].toLowerCase();
        if (!isNaN(parseInt(p2, 10))) {
          updateAction = 'clear_by_id';
          updateTargetId = parseInt(p2, 10);
        } else if (['usa', 'totaltvusa', 'totaltv_usa'].includes(p2)) {
          updateAction = 'clear_agent';
          updateAgent = 'usa';
        } else if (['lat', 'latina', 'tvtotal24', 'tvtotal'].includes(p2)) {
          updateAction = 'clear_agent';
          updateAgent = 'lat';
        } else if (['all', 'todos', 'ambos'].includes(p2)) {
          updateAction = 'clear_all';
          updateAgent = 'all';
        } else {
          errorMessage = `⚠️ Parámetro de eliminación no válido: "<code>${escapeHtml(parts[2])}</code>".\nUso: <code>/update clear &lt;ID&gt;</code> (ej: <code>/update clear 2</code>)\nO: <code>/update &lt;usa|lat|all&gt; clear</code>`;
        }
      } else {
        updateAction = 'clear_all';
        updateAgent = 'all';
      }
    } else if (!isNaN(parseInt(p1, 10))) {
      // Case: /update <id> (e.g. /update 2 clear or /update 2)
      updateAction = 'clear_by_id';
      updateTargetId = parseInt(p1, 10);
    } else if (['usa', 'totaltvusa', 'totaltv_usa'].includes(p1) || ['lat', 'latina', 'tvtotal24', 'tvtotal'].includes(p1) || ['all', 'todos', 'ambos'].includes(p1)) {
      if (['usa', 'totaltvusa', 'totaltv_usa'].includes(p1)) updateAgent = 'usa';
      if (['lat', 'latina', 'tvtotal24', 'tvtotal'].includes(p1)) updateAgent = 'lat';
      if (['all', 'todos', 'ambos'].includes(p1)) updateAgent = 'all';

      if (parts.length === 2) {
        updateAction = 'clear_agent';
      } else {
        const p2 = parts[2].toLowerCase();
        if (['clear', 'off', 'del', 'delete', 'borrar', 'eliminar', 'desactivar', 'clean'].includes(p2)) {
          if (parts.length >= 4 && !isNaN(parseInt(parts[3], 10))) {
            updateAction = 'clear_by_id';
            updateTargetId = parseInt(parts[3], 10);
          } else {
            updateAction = 'clear_agent';
          }
        } else {
          updateAction = 'set';
          updateSituation = parts.slice(2).join(' ').trim();

          if (!updateSituation) {
            errorMessage = `⚠️ Debes indicar la situación o directiva a transmitir.\nUso: <code>/update ${updateAgent} &lt;descripción de la situación&gt;</code>\nEjemplo: <code>/update ${updateAgent} El webplayer está caído por 24 horas. Indicar que usen la app.</code>`;
          } else {
            // Parse duration
            const now = new Date();
            updateCreatedAt = now.toISOString();

            const minMatch = updateSituation.match(/\b(?:por|for)\s+(\d+)\s*(?:minutos?|mins?|m)\b/i);
            const hrMatch = updateSituation.match(/\b(?:por|for)\s+(\d+)\s*(?:horas?|hrs?|h)\b/i) || updateSituation.match(/\b(\d+)\s*(?:horas?|hrs?|h)\b/i);
            const dayMatch = updateSituation.match(/\b(?:por|for)\s+(\d+)\s*(?:d[ií]as?|days?|d)\b/i) || updateSituation.match(/\b(\d+)\s*(?:d[ií]as?|days?|d)\b/i);

            if (minMatch) {
              const mins = parseInt(minMatch[1], 10);
              updateDurationText = `${mins} minutos`;
              const exp = new Date(now.getTime() + mins * 60 * 1000);
              updateExpiresAt = exp.toISOString();
            } else if (hrMatch) {
              const hrs = parseInt(hrMatch[1], 10);
              updateDurationText = `${hrs} horas`;
              const exp = new Date(now.getTime() + hrs * 60 * 60 * 1000);
              updateExpiresAt = exp.toISOString();
            } else if (dayMatch) {
              const days = parseInt(dayMatch[1], 10);
              updateDurationText = `${days} días`;
              const exp = new Date(now.getTime() + days * 24 * 60 * 60 * 1000);
              updateExpiresAt = exp.toISOString();
            } else if (/\b(hasta nuevo aviso|indefinido|sin vencimiento|until further notice)\b/i.test(updateSituation)) {
              updateDurationText = 'hasta nuevo aviso';
              updateExpiresAt = '';
            } else {
              updateDurationText = 'hasta nuevo aviso';
              updateExpiresAt = '';
            }
          }
        }
      }
    } else {
      errorMessage = `⚠️ Parámetro no reconocido: "<code>${escapeHtml(parts[1])}</code>".\nUso: <code>/update &lt;usa|lat|all&gt; &lt;situación / directiva&gt;</code>\nOpciones:\n• <code>/update status</code> (ver directivas e IDs activos)\n• <code>/update clear &lt;ID&gt;</code> (eliminar una directiva específica)\n• <code>/update &lt;usa|lat|all&gt; clear</code> (eliminar directivas de un agente)\n• <code>/update usa El webplayer está caído por 24 horas.</code>`;
    }
  }
} else if (command === '/card2track' || command === '/c2track') {
  isCard2Track = true;
  if (parts.length >= 2 && parts[1].trim() !== '') {
    trackingAddress = parts.slice(1).join(' ').trim();
  } else {
    errorMessage = `⚠️ Sintaxis incompleta para ${command}.\nUso: <code>${command} &lt;tracking_address&gt;</code>\nEjemplo: <code>${command} oxVo4FQwRDd...</code>`;
  }
} else if (command === '/card2crypto' || command === '/c2c' || command === '/nowpayments' || command === '/pdcash' || command === '/blink') {
  if (command === '/card2crypto' || command === '/c2c') isCard2Crypto = true;
  if (command === '/nowpayments') isNowPayments = true;
  if (command === '/pdcash') isPdCash = true;
  if (command === '/blink') isBlink = true;

  if (parts.length >= 3) {
    baseAmount = parseFloat(parts[1]);
    percentage = parseFloat(parts[2]);

    // Validar números
    if (isNaN(baseAmount) || baseAmount <= 0) {
      errorMessage = `⚠️ El monto debe ser un número mayor a 0.\nEjemplo: <code>${command} 30 10 ttv0810a</code>`;
    } else if (isNaN(percentage)) {
      errorMessage = `⚠️ El porcentaje debe ser un número válido (ej. 10 o -20).\nEjemplo: <code>${command} 100 -20 ttv0810b</code>`;
    } else {
      // Calcular monto final
      finalAmount = parseFloat((baseAmount * (1 + percentage / 100)).toFixed(2));

      // Asignar u obtener orden opcional
      if (parts.length >= 4 && parts[3].trim() !== '') {
        orderid = parts[3].trim();
      } else {
        const now = new Date();
        const mm = String(now.getMonth() + 1).padStart(2, '0');
        const dd = String(now.getDate()).padStart(2, '0');
        orderid = `ttv-${mm}${dd}`;
      }
    }
  } else {
    errorMessage = `⚠️ Sintaxis incompleta para ${command}.\nUso: <code>${command} monto porcentaje [orden]</code>\nEjemplos:\n<code>${command} 24 10 Alvez</code>\n<code>${command} 15 -20 250150</code>`;
  }
} else if (command === '/agent' || command === '/agente') {
  isAgent = true;
  if (parts.length >= 3) {
    const rawConvId = parts[1];
    const convId = parseInt(rawConvId, 10);
    const instructionText = parts.slice(2).join(' ').trim();

    if (isNaN(convId) || convId <= 0) {
      errorMessage = `⚠️ El número de conversación debe ser un valor numérico entero (ej. 1323).\nUso: <code>${command} &lt;id_conversacion&gt; &lt;instruccion&gt;</code>\nEjemplo: <code>${command} 1323 envia instrucciones para instalar en iphone</code>`;
    } else if (!instructionText) {
      errorMessage = `⚠️ Debes indicar la instrucción que el Agente IA debe ejecutar.\nUso: <code>${command} &lt;id_conversacion&gt; &lt;instruccion&gt;</code>\nEjemplo: <code>${command} 1323 envia instrucciones para instalar en iphone</code>`;
    } else {
      conversationId = convId;
      instruction = instructionText;
    }
  } else {
    errorMessage = `⚠️ Sintaxis incompleta para /agent.\nUso: <code>${command} &lt;id_conversacion&gt; &lt;instruccion&gt;</code>\nEjemplo: <code>${command} 1323 envia instrucciones para instalar en iphone</code>`;
  }
}

return {
  json: {
    chatId,
    command,
    isCard2Crypto,
    isNowPayments,
    isPdCash,
    isBlink,
    isAgent,
    isCard2Track,
    isUpdate,
    updateAction,
    updateAgent,
    updateSituation,
    updateDurationText,
    updateCreatedAt,
    updateExpiresAt,
    updateTargetId,
    isHelp,
    helpText,
    trackingAddress,
    conversation_id: conversationId,
    instruction,
    isValid: (isCard2Crypto || isNowPayments || isPdCash || isBlink || isAgent || isCard2Track || isUpdate || isHelp) && !errorMessage,
    baseAmount,
    percentage,
    amount: finalAmount,
    orderid,
    errorMessage,
    rawText: messageText
  }
};

