const item = $input.item.json;
const trackingAddr = $('Parsear y Calcular Comando').item.json.trackingAddress;
const chatId = $('Parsear y Calcular Comando').item.json.chatId;

const status = (item.status || 'desconocido').toUpperCase();
const coin = (item.coin || item.currency || 'USDC').toUpperCase();

let statusEmoji = '🔍';
if (['PAID', 'CONFIRMED', 'FORWARDED', 'COMPLETED', 'SUCCESS'].includes(status)) {
  statusEmoji = '✅';
} else if (['UNPAID', 'PENDING', 'WAITING', 'IN_PROGRESS'].includes(status)) {
  statusEmoji = '⏳';
} else if (['EXPIRED', 'FAILED', 'CANCELLED', 'ERROR'].includes(status)) {
  statusEmoji = '❌';
}

const valueCoin = item.value_coin !== undefined && item.value_coin !== '' ? item.value_coin : (item.amount || '0');
const valueNet = item.value_forwarded_coin !== undefined && item.value_forwarded_coin !== '' ? item.value_forwarded_coin : (item.value_forwarded || 'Pendiente');
const addressIn = item.address_in || item.polygon_address_in || item.address || 'No especificada';
const txidIn = item.txid_in || 'N/A';
const txidOut = item.txid_out || 'N/A';

let text = `${statusEmoji} <b>Estado de Pago Card2Crypto</b>\n\n`;
text += `📊 <b>Estado:</b> <code>${status}</code>\n`;
text += `💵 <b>Monto Recibido:</b> $${valueCoin} ${coin}\n`;
text += `📥 <b>Monto Payout / Neto:</b> $${valueNet} ${coin}\n`;
text += `👛 <b>Dirección Depósito:</b>\n<code>${addressIn}</code>\n`;

if (txidIn !== 'N/A') {
  text += `🔗 <b>TXID Entrada:</b>\n<code>${txidIn}</code>\n`;
}

if (txidOut !== 'N/A') {
  text += `🆔 <b>TXID Payout / Salida:</b>\n<code>${txidOut}</code>\n`;
}

text += `\n🔑 <b>Tracking Token:</b>\n<code>${trackingAddr}</code>`;

return {
  json: {
    chatId,
    text,
    status,
    rawResponse: item
  }
};

const cmdData = $('Parsear y Calcular Comando').first().json || {};
const action = cmdData.updateAction || 'status';
const targetAgent = cmdData.updateAgent || 'all';
const targetSituation = cmdData.updateSituation || '';
const durationText = cmdData.updateDurationText || 'hasta nuevo aviso';
const createdAt = cmdData.updateCreatedAt || new Date().toISOString();
const expiresAt = cmdData.updateExpiresAt || '';
const targetId = cmdData.updateTargetId;
const chatId = cmdData.chatId;

// Get all rows from previous dataTable node
let allRows = [];
try {
  allRows = $input.all().map(item => item.json).filter(r => r && (r.id !== undefined || r.situation));
} catch (e) {}

const now = new Date();

function escapeHtml(str) {
  if (!str) return '';
  return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function formatAgent(agent) {
  if (agent === 'usa') return '🇺🇸 TotalTv USA';
  if (agent === 'lat') return '🌎 TVTotal24 Latina';
  return '🌐 Ambos Agentes (ALL)';
}

function formatDate(isoStr) {
  if (!isoStr) return 'Hasta nuevo aviso (Sin vencimiento)';
  try {
    const d = new Date(isoStr);
    return d.toLocaleString('es-ES', { timeZone: 'America/Caracas', dateStyle: 'short', timeStyle: 'short' }) + ' (Hora Caracas)';
  } catch (e) {
    return isoStr;
  }
}

// Identify active non-expired rows
const activeRows = allRows.filter(r => {
  if (r.is_active === false || r.is_active === 'false') return false;
  if (r.expires_at && String(r.expires_at).trim() !== '') {
    const exp = new Date(r.expires_at);
    if (!isNaN(exp.getTime()) && now > exp) return false;
  }
  return true;
});

let messageText = '';

if (action === 'status') {
  const usaRows = activeRows.filter(r => r.agent === 'usa');
  const latRows = activeRows.filter(r => r.agent === 'lat');
  const allAgentsRows = activeRows.filter(r => r.agent === 'all');

  let output = '📢 <b>Estado Actual de Situaciones Temporales de Agentes IA:</b>\n\n';

  output += '🇺🇸 <b>TotalTv USA:</b>\n';
  if (usaRows.length > 0) {
    for (const r of usaRows) {
      output += `• <b>[ID: ${r.id}]</b> <i>"${escapeHtml(r.situation)}"</i>\n  ⏳ Vigencia: <code>${r.duration_text || 'Activa'}</code> | Vence: <code>${formatDate(r.expires_at)}</code>\n`;
    }
  } else {
    output += '• <i>Operación normal estándar (sin directivas especiales activas).</i>\n';
  }
  output += '\n';

  output += '🌎 <b>TVTotal24 Latina:</b>\n';
  if (latRows.length > 0) {
    for (const r of latRows) {
      output += `• <b>[ID: ${r.id}]</b> <i>"${escapeHtml(r.situation)}"</i>\n  ⏳ Vigencia: <code>${r.duration_text || 'Activa'}</code> | Vence: <code>${formatDate(r.expires_at)}</code>\n`;
    }
  } else {
    output += '• <i>Operación normal estándar (sin directivas especiales activas).</i>\n';
  }
  output += '\n';

  output += '🌐 <b>Ambos Agentes (Global / ALL):</b>\n';
  if (allAgentsRows.length > 0) {
    for (const r of allAgentsRows) {
      output += `• <b>[ID: ${r.id}]</b> <i>"${escapeHtml(r.situation)}"</i>\n  ⏳ Vigencia: <code>${r.duration_text || 'Activa'}</code> | Vence: <code>${formatDate(r.expires_at)}</code>\n`;
    }
  } else {
    output += '• <i>Ninguna directiva global activa.</i>\n';
  }
  output += '\n';

  output += 'ℹ️ <i>Para agregar:</i> <code>/update &lt;usa|lat|all&gt; &lt;situación&gt;</code>\n';
