const enOverrideRegex = /(\bin\s+english\b|\blanguage\s+is\s+english\b|\binstruct(ions)?\s+in\s+english\b|\benglish\s+language\b|\ben\s+ingl[eé]s\b|\bidioma\s+ingl[eé]s\b|\brespond\s+in\s+english\b|\bwrite\s+in\s+english\b)/i;
