const esWordRegex = /\b(hola|buen|buenos|buenas|dias|días|tardes|noches|por favor|ayuda|gracias|precio|precios|plan|planes|cuenta|cuentas|pago|pagos|pagar|renovaci[oó]n|renovar|mes|meses|a[ñn]o|a[ñn]os|dispositivo|dispositivos|prueba|demo|servicio|activar|comprobante|listo|transferencia|aqui|ac[aá]|envi[eéo]|enviado|gustar[íi]a|quiero|interesad[oa]|qu[eé]|c[oó]mo|d[oó]nde|cu[aá]ndo|por qu[eé]|porque|saludos|el|la|los|las|un|una|mi|mis|tu|tus|su|sus|es|son|est[aá]|tengo|tiene|pantalla|clave|tarjeta|dinero|soporte|canal|canales)\b/gi;
const enWordRegex = /\b(hi|hello|hey|good|morning|afternoon|evening|please|help|thank|thanks|thank you|price|prices|plan|plans|account|accounts|payment|payments|pay|renewal|renew|month|months|year|years|device|devices|trial|demo|service|services|activate|receipt|done|transfer|here|sent|would|like|want|interested|subscrib|how|what|where|when|why|who|did|can|could|i|you|he|she|it|we|they|my|your|the|is|are|am|do|does|did|have|has|take|card|money|cash|free|need|support|app|firestick|tv|screen|channel|channels|test|buy)\b/gi;

let isEnglish = false;
if (enOverrideRegex.test(instruction)) {
  isEnglish = true;
} else if (esOverrideRegex.test(instruction)) {
