    enCount += (text.match(enWordRegex) || []).length;
    esCount += (text.match(esWordRegex) || []).length;
  }
  if (enCount > esCount) isEnglish = true;
  else if (esCount > enCount) isEnglish = false;
  else isEnglish = (!isTVTotal24);
}

